commits.content:
/* 問題一覧画面のスタイル */
table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
}
th, td {
    border: 1px solid #ddd;
    padding: 8px;
    text-align: left;
}

/* 問題回答画面のスタイル */
.question-show-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 20px;
    background-color: #f5f5f5;
    border-radius: 8px;
}
.question-area, .choices-area {
    max-width: 900px;
    margin: 0 auto;
    font-size: 1.1rem;
}
.choice-box {
    padding: 12px 16px;
    margin-bottom: 10px;
    border: 1px solid #ccc;
    border-radius: 6px;
    background: #f9f9f9;
}
.choice-box:hover {
    background: #eef;
}
.choice-box input[type="checkbox"] {
    margin-right: 10px;
    transform: scale(1.2);
}
.choice-box label {
    cursor: pointer;
    display: flex;
    align-items: center;
}
.button-area {
    margin-top: 20px;
}
.button {
    background-color: #4CAF50;
    color: white;
    padding: 10px 20px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
}
.button:hover {
    background-color: #45a049;
}
/* フォームのスタイル調整 */
#choices {
    margin-top: 20px;
}
#choices .choice-field {
    margin-bottom: 15px;
}
#choices .choice-field:last-child {
    margin-bottom: 0;
}
